/* Shopify adapter for the Many Faces Espresso site script (prepended to site/src/app.js by build.mjs).
   The catalog is the research data (snippets/research-data) narrowed to the products published in the store
   (snippets/store-data). If the store has no products yet, the full research catalog shows, so the theme works before
   the CSV import. Store title, vendor, photo and page URL win over the research record. */
window.MFE_DATA = (function () {
  const research = window.MFE_RESEARCH || {products: [], offers: []};
  const store = Array.isArray(window.MFE_STORE) ? window.MFE_STORE : [];
  const byHandle = new Map(store.map(s => [s.handle, s]));
  const CATEGORY = {'espresso machine': 'machine', machine: 'machine', grinder: 'grinder', accessory: 'accessory', 'care & cleaning': 'maintenance', maintenance: 'maintenance'};
  const WORKFLOWS = ['automatic', 'hands-on', 'assisted', 'universal'];
  const fromStore = (p, s) => ({...p, name: s.title || p.name, brand: s.vendor || p.brand, image: s.image || null, imageAlt: s.image_alt || '', url: s.url || null});
  let products = research.products.map(p => byHandle.has(p.id) ? fromStore(p, byHandle.get(p.id)) : p);
  if (store.length) {
    const known = new Set(products.map(p => p.id));
    products = products.filter(p => byHandle.has(p.id));
    // Products added in Shopify only: type sets the category; tags `workflow:<x>` and `requires-grinder` feed the tools.
    for (const s of store) {
      const category = CATEGORY[String(s.type || '').toLowerCase()];
      if (known.has(s.handle) || !category) continue;
      const tag = k => (s.tags || []).map(String).find(t => t.startsWith(k + ':'))?.slice(k.length + 1);
      const workflow = WORKFLOWS.includes(tag('workflow')) ? tag('workflow') : category === 'machine' ? 'assisted' : category === 'grinder' ? 'hands-on' : 'universal';
      products.push(fromStore({id: s.handle, name: s.title, brand: s.vendor || '', category, workflow, price: null, dimensions: null, source: null, checked: 'not recorded',
        requiresGrinder: (s.tags || []).includes('requires-grinder'), portafilter: null, notes: 'Added in the store; research details not recorded yet.', included: []}, s));
    }
  }
  const ids = new Set(products.map(p => p.id));
  return {products, offers: research.offers.filter(o => ids.has(o.productId))};
})();

/* Pages other than Home (product, collection, search, cart, 404) use the Liquid header; this runs its phone menu. */
document.addEventListener('click', e => {
  const b = e.target.closest('[data-mfe-menu]'); if (!b) return;
  const nav = document.querySelector('.mobile-nav'); const open = !nav.classList.contains('open');
  nav.classList.toggle('open', open); b.setAttribute('aria-expanded', String(open));
});
document.addEventListener('keydown', e => {
  const nav = document.querySelector('.mobile-nav.open'), b = document.querySelector('[data-mfe-menu]');
  if (e.key !== 'Escape' || !nav || !b) return;
  nav.classList.remove('open'); b.setAttribute('aria-expanded', 'false'); b.focus();
});

