let stopRitualFilms=()=>{};
const filmPausedByUser=new Set();
function setupRitualFilms(){stopRitualFilms();const videos=[...el.querySelectorAll('.ritual-video')];if(!videos.length)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)'),cleanups=[];
 for(const video of videos){const frame=video.parentElement,button=frame.querySelector('.ritual-toggle'),status=frame.querySelector('.ritual-status');let near=false,visible=false,observer,failed=false,retried=false,autoPause=false;const id=video.dataset.mp4;
 const load=()=>{if(!video.getAttribute('src')){video.src=video.canPlayType('video/mp4; codecs="avc1.42E01E"')?video.dataset.mp4:video.dataset.webm;video.load()}};
 const sync=()=>{button.textContent=video.paused?'Play film':'Pause film';button.setAttribute('aria-label',(video.paused?'Play ':'Pause ')+video.getAttribute('aria-label'))};
 const pause=()=>{if(!video.paused){autoPause=true;video.pause()}};
 const play=(manual=false)=>{if(failed||document.hidden)return;if(!manual&&(!visible||reduced.matches||navigator.connection?.saveData||filmPausedByUser.has(id)))return;load();video.muted=true;video.play().catch(sync)};
 const preference=()=>{if(reduced.matches||navigator.connection?.saveData)pause();else play()};
 video.addEventListener('play',()=>{autoPause=false;sync()});video.addEventListener('pause',()=>{if(!autoPause&&!video.ended)filmPausedByUser.add(id);autoPause=false;sync()});
 video.addEventListener('error',()=>{if(!retried&&video.getAttribute('src')!==video.dataset.webm){retried=true;video.src=video.dataset.webm;video.load();play()}else{failed=true;pause();video.hidden=true;frame.style.backgroundImage=`url("${video.poster}")`;button.hidden=true;status.hidden=false}});
 button.addEventListener('click',()=>{if(video.paused){filmPausedByUser.delete(id);play(true)}else{filmPausedByUser.add(id);video.pause()}sync()});
 const visibility=()=>document.hidden?pause():play();document.addEventListener('visibilitychange',visibility);reduced.addEventListener('change',preference);
 if('IntersectionObserver' in window){observer=new IntersectionObserver(([entry])=>{near=entry.isIntersecting;visible=entry.intersectionRatio>=.35;if(near&&!reduced.matches&&!navigator.connection?.saveData)load();if(visible)play();else pause()},{threshold:[0,.35]});observer.observe(video)}else{button.hidden=false}
 cleanups.push(()=>{observer?.disconnect();document.removeEventListener('visibilitychange',visibility);reduced.removeEventListener('change',preference);pause()});sync();
 }stopRitualFilms=()=>cleanups.forEach(fn=>fn());
}

function pageHero(k,title,sub){const images={'The collection':['shop-and-compare','Two espresso workflows side by side'],'The personal espresso finder':['hands-on-espresso','An espresso ritual with machine and grinder'],'The coffee station studio':['coffee-station','An organized home coffee station'],'Measure before you buy':['coffee-station','A counter and open shelving around a coffee station'],'Buy less, improve more':['upgrade-espresso','A grinder, scale and portafilter'],'Side by side':['shop-and-compare','Two different espresso workflows'],'Your shortlist':['morning-ritual','Coffee cups ready for a quiet morning'],'The espresso edit':[getQuery().get('article')==='ownership'?'coffee-care':getQuery().get('article')==='space'?'coffee-station':'morning-ritual','A considered home coffee ritual'],'Our point of view':['morning-ritual','Coffee and a moment to pause']};const pic=images[k],visual=pic?editorialPhoto(...pic):'';return `<div class="page-hero"><div class="container ${visual?'page-hero-layout':''}"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${visual}</div></div>${filmSection(k)}`}
let heroMotionPaused=false,stopHeroMotion=()=>{};
function heroMotion(){const src=window.MFE_HERO_VIDEO===undefined?'./assets/hero-motion.mp4':window.MFE_HERO_VIDEO;return src?`<video class="hero-video" muted loop playsinline preload="none" aria-hidden="true" tabindex="-1" data-src="${html(src)}" data-webm="${html(window.MFE_HERO_WEBM===undefined?(window.MFE_HERO_VIDEO===undefined?'./assets/hero-motion.webm':''):(window.MFE_HERO_WEBM||''))}"></video><button type="button" class="hero-motion-toggle" aria-label="Play background video" hidden>Play motion</button>`:''}
function setupHeroMotion(){stopHeroMotion();const video=$('.hero-video'),button=$('.hero-motion-toggle');if(!video||!button)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let observer,visible=true,triedWebm=false;
 const source=()=>video.canPlayType('video/mp4; codecs="avc1.42E01E"')?video.dataset.src:(video.dataset.webm||video.dataset.src);
 const sync=()=>{button.textContent=video.paused?'Play motion':'Pause motion';button.setAttribute('aria-label',video.paused?'Play background video':'Pause background video')};
 const play=()=>{if(reduced.matches||navigator.connection?.saveData||heroMotionPaused||!visible||document.hidden)return;video.muted=true;if(!video.getAttribute('src'))video.src=source();video.play().catch(()=>{sync()})};
 const preference=()=>{if(reduced.matches||navigator.connection?.saveData){video.pause();video.removeAttribute('src');video.load();video.classList.remove('is-playing');button.hidden=true}else{button.hidden=false;play()}};
 video.addEventListener('playing',()=>{video.classList.add('is-playing');sync()});video.addEventListener('pause',sync);video.addEventListener('error',()=>{video.classList.remove('is-playing');if(!triedWebm&&video.dataset.webm&&video.getAttribute('src')!==video.dataset.webm){triedWebm=true;video.src=video.dataset.webm;play()}else{video.pause();button.hidden=true}});
 button.addEventListener('click',()=>{heroMotionPaused=!video.paused;if(heroMotionPaused)video.pause();else play();sync()});
 const visibility=()=>document.hidden?video.pause():play();document.addEventListener('visibilitychange',visibility);reduced.addEventListener('change',preference);
 if('IntersectionObserver' in window){observer=new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;if(visible)play();else video.pause()});observer.observe(video.parentElement)}
 stopHeroMotion=()=>{observer?.disconnect();reduced.removeEventListener('change',preference);document.removeEventListener('visibilitychange',visibility);video.pause()};preference();
}
